<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { authorizedRequest } from './auth.js'
import { allowedDepartmentParents, departmentName } from './organization.js'
const data = ref({ departments: [], roles: [], users: [] }), error = ref(''), message = ref('')
const department = ref({ name: '', parentId: null }), roleName = ref(''), user = ref({ username: '', password: '', departmentId: null })
const moveDialog = ref(false), moveTarget = ref(null), moveParent = ref(null)
const auditAction = ref(''), auditEvents = ref([]), auditMore = ref(false), auditLoadedAction = ref(''), auditCursors = ref([null]), auditPage = ref(0), auditBusy = ref(false)
const tab = ref('departments'), search = ref(''), pageSize = 10
const pages = ref({ departments: 1, roles: 1, users: 1 })
const departmentDialog = ref(false), roleDialog = ref(false), userDialog = ref(false), permissionDialog = ref(false), roleAssignmentDialog = ref(false)
const editRole = ref(null), editPermissions = ref([]), editUser = ref(null), editRoles = ref([])
const filtered = computed(() => { const q = search.value.trim().toLocaleLowerCase(); const match = value => !q || String(value).toLocaleLowerCase().includes(q); return { departments: data.value.departments.filter(x => match(x.name) || match(x.id)), roles: data.value.roles.filter(x => match(x.name) || match(x.id)), users: data.value.users.filter(x => match(x.username) || match(departmentName(data.value.departments, x.departmentId))) } })
function page(items, name) { const index = Math.min(pages.value[name], Math.max(1, Math.ceil(items.length / pageSize))); return items.slice((index - 1) * pageSize, index * pageSize) }
watch(search, () => { pages.value = { departments: 1, roles: 1, users: 1 } })
watch(filtered, result => { for (const name of ['departments', 'roles', 'users']) pages.value[name] = Math.min(pages.value[name], Math.max(1, Math.ceil(result[name].length / pageSize))) })
const passwordDialog = ref(false), passwordTarget = ref(null), newPassword = ref('')
const permissions = [ ['organization.manage','组织与权限管理'], ['datasource.manage','数据源与资产管理'], ['dataset.read','数据集读取'], ['workflow.validate','工作流校验'], ['workflow.manage','任务与工作流管理'], ['service.manage','数据服务管理'], ['report.manage','报表管理'] ]
async function load() { try { const response = await fetch('/api/organization', { credentials: 'same-origin' }); if (!response.ok) throw new Error(response.status === 403 ? '当前账号没有组织管理权限' : '无法读取组织信息'); data.value = await response.json() } catch (e) { error.value = e.message } }
async function post(path, body, success) { try { error.value = ''; const response = await authorizedRequest(`/api/organization${path}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }); if (!response.ok) throw new Error(response.status === 403 ? '当前账号没有组织管理权限' : response.status === 409 ? '名称或配置与现有数据冲突' : '保存失败，请检查输入'); message.value = success; await load(); return true } catch (e) { error.value = e.message; return false } }
async function loadAudit(index = 0, reset = false) {
  if (auditBusy.value) return
  auditBusy.value = true
  try {
    const action = auditAction.value.trim()
    if (reset || action !== auditLoadedAction.value) { index = 0; auditCursors.value = [null] }
    const query = new URLSearchParams({ limit: '10' })
    if (action) query.set('action', action)
    if (auditCursors.value[index] != null) query.set('beforeId', auditCursors.value[index])
    const response = await fetch(`/api/organization/audit?${query}`, { credentials: 'same-origin' })
    if (!response.ok) throw new Error('读取审计记录失败，请检查权限')
    const result = await response.json(); auditEvents.value = result; auditPage.value = index; auditMore.value = result.length === 10; auditLoadedAction.value = action; error.value = ''
  } catch (e) { error.value = e.message } finally { auditBusy.value = false }
}
function nextAudit() { if (!auditMore.value || !auditEvents.value.length) return; const next = auditPage.value + 1; auditCursors.value = [...auditCursors.value.slice(0, next), auditEvents.value.at(-1).id]; loadAudit(next) }
function changeTab(name) { search.value = ''; if (name === 'audit' && !auditEvents.value.length) loadAudit(0, true) }
function openPermissions(item) { editRole.value = item; editPermissions.value = [...item.permissions]; permissionDialog.value = true }
function openRoles(item) { editUser.value = item; editRoles.value = [...item.roles]; roleAssignmentDialog.value = true }
async function savePermissions() { if (await post(`/roles/${editRole.value.id}/permissions`, { permissions: editPermissions.value }, '角色权限已更新')) permissionDialog.value = false }
async function saveRoles() { if (await post(`/users/${editUser.value.id}/roles`, { roles: editRoles.value }, '用户角色已更新')) roleAssignmentDialog.value = false }
function roleLabels(ids) { return ids.map(id => data.value.roles.find(r => r.id === id)?.name ?? `角色 ${id}`).join('、') || '暂无角色' }
function permissionLabels(ids) { return ids.map(id => permissions.find(([value]) => value === id)?.[1] ?? id).join('、') || '暂无权限' }
async function createDepartment() { if (await post('/departments', department.value, '部门已创建')) { department.value = { name: '', parentId: null }; departmentDialog.value = false } }
async function createRole() { if (await post('/roles', { name: roleName.value }, '角色已创建')) { roleName.value = ''; roleDialog.value = false } }
async function createUser() { if (await post('/users', user.value, '用户已创建')) { user.value = { username: '', password: '', departmentId: null }; userDialog.value = false } }
function selectMove(item) { moveTarget.value = item; moveParent.value = item.parentId; moveDialog.value = true }
async function moveDepartment() { if (await post(`/departments/${moveTarget.value.id}/parent`, { parentId: moveParent.value }, '部门上级已更新')) moveDialog.value = false }
function setPassword(item) { passwordTarget.value = item; newPassword.value = ''; passwordDialog.value = true }
async function resetPassword() { if (await post(`/users/${passwordTarget.value.id}/password`, { password: newPassword.value }, '密码已重置，原会话将失效')) { passwordDialog.value = false; newPassword.value = '' } }
onMounted(load)
</script>
<template>
<section><div class="page-heading"><div><p class="kicker">系统管理</p><h1>组织与权限</h1><p class="subheading">管理部门、账号、角色及功能权限。</p></div><el-button @click="load">刷新</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/><el-alert v-if="message" :title="message" type="success" :closable="false" show-icon/>
<el-tabs v-model="tab" @tab-change="changeTab"><el-tab-pane label="部门" name="departments"><div class="toolbar"><el-input v-model="search" clearable placeholder="搜索部门或编号"/><el-button type="primary" @click="departmentDialog = true">新建部门</el-button></div><el-table :data="page(filtered.departments, 'departments')"><el-table-column prop="id" label="编号"/><el-table-column prop="name" label="部门"/><el-table-column label="上级部门"><template #default="scope">{{ departmentName(data.departments, scope.row.parentId) }}</template></el-table-column><el-table-column label="操作"><template #default="scope"><el-button text @click="selectMove(scope.row)">调整上级</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="pages.departments" class="pagination" layout="total, prev, pager, next" :page-size="pageSize" :total="filtered.departments.length"/></el-tab-pane>
<el-tab-pane label="角色" name="roles"><div class="toolbar"><el-input v-model="search" clearable placeholder="搜索角色或编号"/><el-button type="primary" @click="roleDialog = true">新建角色</el-button></div><el-table :data="page(filtered.roles, 'roles')"><el-table-column prop="name" label="角色"/><el-table-column label="功能权限" min-width="400"><template #default="scope">{{ permissionLabels(scope.row.permissions) }}</template></el-table-column><el-table-column label="操作"><template #default="scope"><el-button text type="primary" @click="openPermissions(scope.row)">配置权限</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="pages.roles" class="pagination" layout="total, prev, pager, next" :page-size="pageSize" :total="filtered.roles.length"/></el-tab-pane>
<el-tab-pane label="用户" name="users"><div class="toolbar"><el-input v-model="search" clearable placeholder="搜索用户名或部门"/><el-button type="primary" @click="userDialog = true">新建用户</el-button></div><el-table :data="page(filtered.users, 'users')"><el-table-column prop="username" label="用户名"/><el-table-column prop="departmentId" label="部门编号"/><el-table-column label="角色" min-width="230"><template #default="scope">{{ roleLabels(scope.row.roles) }}</template></el-table-column><el-table-column label="状态"><template #default="scope">{{ scope.row.enabled ? '启用' : '停用' }}</template></el-table-column><el-table-column label="操作" min-width="270"><template #default="scope"><el-button text type="primary" @click="openRoles(scope.row)">配置角色</el-button><el-popconfirm :title="scope.row.enabled ? '停用后该用户的现有会话将失效，确定停用？' : '确定启用该用户？'" @confirm="post(`/users/${scope.row.id}/enabled`, { enabled: !scope.row.enabled }, '用户状态已更新')"><template #reference><el-button text>{{ scope.row.enabled ? '停用' : '启用' }}</el-button></template></el-popconfirm><el-button text @click="setPassword(scope.row)">重置密码</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="pages.users" class="pagination" layout="total, prev, pager, next" :page-size="pageSize" :total="filtered.users.length"/></el-tab-pane><el-tab-pane label="审计记录" name="audit"><div class="pane"><div class="row"><el-input v-model="auditAction" placeholder="操作类型（可留空）"/><el-button type="primary" @click="loadAudit(0, true)">查询</el-button></div><p>登录失败等没有关联账号的记录显示为系统或未知账号。</p><el-table :data="auditEvents"><el-table-column prop="occurredAt" label="时间" min-width="170"/><el-table-column label="操作者"><template #default="scope">{{ scope.row.username || '系统或未知账号' }}</template></el-table-column><el-table-column prop="action" label="操作" min-width="160"/><el-table-column prop="objectType" label="对象类型"/><el-table-column prop="objectId" label="对象编号"/><el-table-column prop="result" label="结果"/></el-table><div class="pagination"><el-button :disabled="auditPage === 0 || auditBusy" @click="loadAudit(auditPage - 1)">上一页</el-button><span>第 {{ auditPage + 1 }} 页</span><el-button :disabled="!auditMore || auditBusy" @click="nextAudit">下一页</el-button></div></div></el-tab-pane></el-tabs><el-dialog v-model="departmentDialog" title="新建部门" width="min(460px, 95vw)"><el-form label-position="top" @submit.prevent="createDepartment"><el-form-item label="部门名称"><el-input v-model="department.name"/></el-form-item><el-form-item label="上级部门"><el-select v-model="department.parentId" clearable placeholder="可不选"><el-option v-for="d in data.departments" :key="d.id" :label="d.name" :value="d.id"/></el-select></el-form-item><el-button type="primary" native-type="submit">创建部门</el-button></el-form></el-dialog><el-dialog v-model="roleDialog" title="新建角色" width="min(460px, 95vw)"><el-form label-position="top" @submit.prevent="createRole"><el-form-item label="角色名称"><el-input v-model="roleName"/></el-form-item><el-button type="primary" native-type="submit">创建角色</el-button></el-form></el-dialog><el-dialog v-model="userDialog" title="新建用户" width="min(460px, 95vw)" @closed="user.password = ''"><el-form label-position="top" @submit.prevent="createUser"><el-form-item label="用户名"><el-input v-model="user.username" autocomplete="off"/></el-form-item><el-form-item label="初始密码（至少 12 字符）"><el-input v-model="user.password" type="password" show-password autocomplete="new-password"/></el-form-item><el-form-item label="部门"><el-select v-model="user.departmentId"><el-option v-for="d in data.departments" :key="d.id" :label="d.name" :value="d.id"/></el-select></el-form-item><el-button type="primary" native-type="submit">创建用户</el-button></el-form></el-dialog><el-dialog v-model="permissionDialog" title="配置角色权限" width="min(460px, 95vw)"><p>为 {{ editRole?.name }} 选择功能权限。</p><el-select v-model="editPermissions" multiple><el-option v-for="[value,label] in permissions" :key="value" :value="value" :label="label"/></el-select><template #footer><el-button @click="permissionDialog = false">取消</el-button><el-button type="primary" @click="savePermissions">保存权限</el-button></template></el-dialog><el-dialog v-model="roleAssignmentDialog" title="配置用户角色" width="min(460px, 95vw)"><p>为 {{ editUser?.username }} 选择角色。</p><el-select v-model="editRoles" multiple><el-option v-for="r in data.roles" :key="r.id" :label="r.name" :value="r.id"/></el-select><template #footer><el-button @click="roleAssignmentDialog = false">取消</el-button><el-button type="primary" @click="saveRoles">保存角色</el-button></template></el-dialog><el-dialog v-model="moveDialog" title="调整上级部门" width="min(460px, 95vw)"><p>为 {{ moveTarget?.name }} 选择上级部门，留空表示设为顶级部门。</p><el-select v-model="moveParent" clearable placeholder="无上级部门"><el-option v-for="d in allowedDepartmentParents(data.departments, moveTarget?.id)" :key="d.id" :label="d.name" :value="d.id"/></el-select><template #footer><el-button @click="moveDialog = false">取消</el-button><el-button type="primary" @click="moveDepartment">保存</el-button></template></el-dialog><el-dialog v-model="passwordDialog" title="重置密码" width="min(460px, 95vw)" @closed="newPassword = ''"><p>为 {{ passwordTarget?.username }} 设置新密码，原有会话将失效。</p><el-input v-model="newPassword" type="password" show-password autocomplete="new-password" placeholder="至少 12 字符"/><template #footer><el-button @click="passwordDialog = false">取消</el-button><el-button type="primary" @click="resetPassword">重置密码</el-button></template></el-dialog></section>
</template>
<style scoped>.toolbar{display:flex;gap:12px;margin:16px 0}.toolbar .el-input{width:min(300px,100%)}.pagination{display:flex;justify-content:flex-end;align-items:center;gap:12px;margin:20px 0}.pane{background:white;border:1px solid #e1eae8;padding:20px;margin:16px 0}.row{display:flex;gap:12px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 18px}@media(max-width:700px){.row{flex-wrap:wrap}.grid{grid-template-columns:1fr}}</style>
